def rollout(ops):
    """Bounded upgrade gates; ops owns all actual binaries, sockets and storage."""
    for role in ('old', 'target'):
        result = ops.preflight(role)
        if result['config_ok'] is not True:
            return {'promoted': False, 'reason': 'config'}
        if result['template_ok'] is not True:
            return {'promoted': False, 'reason': 'template'}
    mixed = ops.mixed()
    if not all(mixed[name] is True for name in
               ('different_versions', 'cluster_ready', 'api_ok', 'silence_synced', 'notification_seen')):
        return {'promoted': False, 'reason': 'mixed'}
    final = ops.promote()
    if not all(final[name] is True for name in
               ('target_only', 'cluster_ready', 'silence_preserved', 'notification_seen', 'old_artifacts_retained')):
        return {'promoted': False, 'reason': 'final'}
    return {'promoted': True, 'reason': 'complete'}

