import decimal,json,re
def snapshot(fetch):
 response=fetch()
 if type(response)is not dict or response.get('status')!=200 or type(response.get('body'))is not str:raise ValueError('successful native HTTP response required')
 rows=[]
 for raw in response['body'].split('\n'):
  line=raw.strip()
  if not line or line.startswith('#'):continue
  match=re.fullmatch(r'([a-zA-Z_:][a-zA-Z0-9_:]*)(?:\{(.*)\})?\s+(\S+)',line)
  if match is None:raise ValueError('finite exposition line')
  name,text,number=match.groups();labels={}
  if text:
   for token in re.finditer(r'([a-zA-Z_][a-zA-Z0-9_]*)="((?:\\.|[^"\\])*)"',text):
    key,value=token.groups()
    if key in labels:raise ValueError('duplicate label')
    labels[key]=json.loads('"'+value+'"')
  try:value=decimal.Decimal(number)
  except decimal.InvalidOperation as error:raise ValueError('numeric sample')from error
  rows.append((name,labels,value))
 return rows
def integer(rows,name,labels=None):
 selected=[value for metric,tags,value in rows if metric==name and tags==(labels or{})]
 if len(selected)!=1:raise ValueError('missing/duplicate required sample')
 value=selected[0]
 if not value.is_finite()or value<0 or value!=value.to_integral_value()or value>2**53:raise ValueError('finite exact integer native sample')
 return int(value)
def success(rows,collector):
 if integer(rows,'node_scrape_collector_success',{'collector':collector})!=1:raise ValueError('required native collector failed')

